def min_Ops(arr, n, k):
    """Write a python function to find k number of operations required to make all elements equal.

    In one operation, an element can be incremented by ``k``.  The minimum
    number of operations is therefore obtained by raising every element to
    the largest element.  If some element cannot reach the largest element
    by increments of ``k``, making all elements equal is impossible and
    ``-1`` is returned.
    """
    if arr is None:
        return 0

    values = list(arr)
    if isinstance(n, int) and not isinstance(n, bool) and 0 <= n < len(values):
        values = values[:n]

    if not values:
        return 0

    if k is None or k <= 0:
        return 0 if all(value == values[0] for value in values) else -1

    target = max(values)
    operations = 0
    for value in values:
        difference = target - value
        if difference % k != 0:
            return -1
        operations += difference // k
    return operations
